const body = $json.body || $json;
const g = (k, d = '') => { const v = body[k]; return (v === undefined || v === null || v === '') ? d : v; };
const asBool = (v) => v === true || v === 'true' || v === 'yes' || v === 'on' || v === '1';
const asList = (v) => Array.isArray(v) ? v.filter(Boolean) : (typeof v === 'string' && v.length ? v.split(',').map(s => s.trim()).filter(Boolean) : []);

const intake = {
  trackingId: 'VET-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + $execution.id,
  submittedAt: new Date().toISOString(),
  requesterName: g('requesterName'),
  requesterEmail: g('requesterEmail'),
  department: g('department'),
  productName: g('productName'),
  vendorName: g('vendorName'),
  productUrl: g('productUrl'),
  requestedVersion: g('requestedVersion'),
  businessNeed: g('businessNeed'),
  userCount: g('userCount', '1-10'),
  userTypes: g('userTypes'),
  deploymentTypes: asList(g('deploymentTypes', [])),
  dataTypes: asList(g('dataTypes', [])),
  sensitiveData: asList(g('sensitiveData', [])),
  permissionLevel: g('permissionLevel', 'user'),
  kernelDriver: asBool(g('kernelDriver')),
  browserAllSites: asBool(g('browserAllSites')),
  integrations: asList(g('integrations', [])),
  oauthScopes: g('oauthScopes'),
  aiProcessing: asBool(g('aiProcessing')),
  aiTraining: g('aiTraining', 'unknown'),
  hostingProvider: g('hostingProvider'),
  hostingRegion: g('hostingRegion'),
  authMethods: asList(g('authMethods', [])),
  adminControls: asList(g('adminControls', [])),
  businessCriticality: g('businessCriticality', 'low'),
  existingAlternative: g('existingAlternative'),
  externalSharing: asBool(g('externalSharing')),
  publicFacing: asBool(g('publicFacing')),
  isOpenSource: asBool(g('isOpenSource')),
  githubRepo: g('githubRepo'),
  packageEcosystem: g('packageEcosystem'),
  packageName: g('packageName'),
  vendorPublicCompany: asBool(g('vendorPublicCompany')),
  notes: g('notes')
};

let repoPath = '';
if (intake.githubRepo) {
  repoPath = String(intake.githubRepo).replace(/^https?:\/\/(www\.)?github\.com\//i, '').replace(/\.git$/, '').replace(/\/+$/, '');
  repoPath = repoPath.split('/').slice(0, 2).join('/');
  if (!repoPath.includes('/')) repoPath = '';
}
const ecoMap = { npm: ['npm', 'npm'], pypi: ['PyPI', 'pypi'], python: ['PyPI', 'pypi'], maven: ['Maven', 'maven'], java: ['Maven', 'maven'], go: ['Go', 'go'], cargo: ['crates.io', 'cargo'], rust: ['crates.io', 'cargo'], nuget: ['NuGet', 'nuget'], dotnet: ['NuGet', 'nuget'], rubygems: ['RubyGems', 'rubygems'], ruby: ['RubyGems', 'rubygems'] };
const eco = ecoMap[(intake.packageEcosystem || '').toLowerCase()] || ['npm', 'npm'];
intake.repoPath = repoPath;
intake.osvEcosystem = eco[0];
intake.depsSystem = eco[1];

const flags = [];
if (intake.permissionLevel === 'admin') flags.push('Local administrator privileges requested');
if (intake.permissionLevel === 'system') flags.push('SYSTEM/root privileges requested');
if (intake.kernelDriver) flags.push('Kernel driver or system service');
if (intake.browserAllSites) flags.push('Browser extension reads/changes data on all websites');
if (intake.integrations.some(i => /microsoft|graph|m365|365|google|workspace/i.test(i))) flags.push('Microsoft Graph / Google Workspace integration');
if (intake.integrations.some(i => /email|file|database|sql/i.test(i))) flags.push('Email, file-system, or database access');
if (intake.integrations.some(i => /credential|password|vault/i.test(i))) flags.push('Credential storage');
if (intake.sensitiveData.length) flags.push('Sensitive data in scope: ' + intake.sensitiveData.join(', '));
if (intake.aiProcessing) flags.push('AI processing of company data');
if (intake.aiTraining === 'yes') flags.push('Vendor trains AI models on customer data');
if (intake.externalSharing) flags.push('External sharing functionality');
if (intake.publicFacing) flags.push('Public-facing service');
if (['251-1000', '1000+'].includes(intake.userCount)) flags.push('Large user population (' + intake.userCount + ')');
if (['high', 'critical'].includes(intake.businessCriticality)) flags.push('Business-critical workflow dependency');
if (intake.sensitiveData.length && !intake.authMethods.some(a => /sso|saml|oidc/i.test(a))) flags.push('No SSO despite sensitive data');
if (intake.sensitiveData.length && !intake.authMethods.some(a => /mfa/i.test(a))) flags.push('No enforceable MFA despite sensitive data');

const highPatterns = /privileg|kernel|all websites|graph|workspace|credential|sensitive|ai |trains ai|public-facing|business-critical|sso|mfa/i;
const highFlags = flags.filter(f => highPatterns.test(f));
let riskTier = 1;
if (flags.length > 0 || intake.dataTypes.length > 0 || intake.deploymentTypes.map(d => d.toLowerCase()).includes('saas')) riskTier = 2;
if (highFlags.length > 0) riskTier = 3;
const riskTierLabel = { 1: 'Tier 1 - Low (automated/basic review)', 2: 'Tier 2 - Moderate (security review)', 3: 'Tier 3 - High (full security/vendor assessment)' }[riskTier];

return [{ json: { intake, riskFlags: flags, riskTier, riskTierLabel } }];

const resp = $json;
const vulns = (resp.vulnerabilities || []).map(v => v.cve).filter(Boolean);
const parsed = vulns.map(c => {
  const metrics = c.metrics || {};
  const m3 = (metrics.cvssMetricV31 || metrics.cvssMetricV30 || metrics.cvssMetricV40 || [])[0];
  const m2 = (metrics.cvssMetricV2 || [])[0];
  const cvss = (m3 && m3.cvssData) ? m3.cvssData.baseScore : ((m2 && m2.cvssData) ? m2.cvssData.baseScore : null);
  const severity = (m3 && m3.cvssData && m3.cvssData.baseSeverity) ? m3.cvssData.baseSeverity : ((m2 && m2.baseSeverity) ? m2.baseSeverity : 'UNKNOWN');
  const vector = (m3 && m3.cvssData) ? (m3.cvssData.vectorString || '') : '';
  const descObj = (c.descriptions || []).find(d => d.lang === 'en') || {};
  return { cveId: c.id, cvss, severity, vector, published: c.published, lastModified: c.lastModified, description: (descObj.value || '').slice(0, 350) };
});
parsed.sort((a, b) => (b.cvss || 0) - (a.cvss || 0));
const top = parsed.slice(0, 30);
return [{ json: { totalResults: resp.totalResults || parsed.length, cveCount: parsed.length, cves: top, cveIds: top.map(c => c.cveId).join(','), hasCves: top.length > 0 } }];

let intake = {};
try { intake = $('Normalize Request Data').first().json.intake; } catch (e) {}
const kevCves = ($json.vulnerabilities || []).map(v => v.cve).filter(Boolean);
const seen = new Set();
const matches = [];
for (const c of kevCves) {
  if (seen.has(c.id)) continue;
  seen.add(c.id);
  const descObj = (c.descriptions || []).find(d => d.lang === 'en') || {};
  matches.push({
    cveID: c.id,
    vendorProject: intake.vendorName || '',
    product: intake.productName || '',
    name: c.cisaVulnerabilityName || '',
    dateAdded: c.cisaExploitAdd || '',
    dueDate: c.cisaActionDue || '',
    ransomware: '',
    requiredAction: (c.cisaRequiredAction || '').slice(0, 200),
    summary: (descObj.value || '').slice(0, 300)
  });
}
return [{ json: { kevMatchCount: matches.length, kevMatches: matches.slice(0, 25) } }];

const xml = typeof $json.data === 'string' ? $json.data : '';
const items = [];
const itemRe = /<item>([\s\S]*?)<\/item>/g;
function pick(block, tag) {
  const open = '<' + tag + '>';
  const close = '</' + tag + '>';
  const i = block.indexOf(open);
  if (i === -1) return '';
  const j = block.indexOf(close, i);
  if (j === -1) return '';
  let val = block.slice(i + open.length, j).trim();
  val = val.replace('<![CDATA[', '').replace(']]>', '').trim();
  return val;
}
let m;
while ((m = itemRe.exec(xml)) !== null && items.length < 15) {
  const b = m[1];
  items.push({ title: pick(b, 'title'), link: pick(b, 'link'), pubDate: pick(b, 'pubDate') });
}
return [{ json: { newsCount: items.length, newsItems: items } }];

function safe(name) { try { const it = $(name).first(); return it ? it.json : null; } catch (e) { return null; } }
const base = safe('Normalize & Classify Request') || { intake: {}, riskFlags: [], riskTier: 2, riskTierLabel: 'Tier 2 - Moderate' };
const intake = base.intake || {};
const cveData = safe('Extract CVE Signals') || { cves: [], cveCount: 0, totalResults: 0 };
const epssRaw = safe('EPSS Lookup');
const kevData = safe('Correlate KEV') || { kevMatches: [], kevMatchCount: 0 };
const newsData = safe('Parse Breach News') || { newsItems: [], newsCount: 0 };
const edgarRaw = safe('SEC EDGAR Search');
const github = safe('GitHub Repo Info');
const scorecard = safe('OpenSSF Scorecard');
const osv = safe('OSV Query');
const depsdev = safe('deps.dev Lookup');

const epssMap = {};
if (epssRaw && Array.isArray(epssRaw.data)) {
  for (const row of epssRaw.data) { epssMap[row.cve] = { epss: parseFloat(row.epss), percentile: parseFloat(row.percentile) }; }
}
const cves = (cveData.cves || []).map(c => Object.assign({}, c, { epss: epssMap[c.cveId] ? epssMap[c.cveId].epss : null, epssPercentile: epssMap[c.cveId] ? epssMap[c.cveId].percentile : null }));
const maxCvss = cves.reduce((m, c) => Math.max(m, c.cvss || 0), 0);
const epssMax = cves.reduce((m, c) => Math.max(m, c.epss || 0), 0);
const criticalCount = cves.filter(c => (c.cvss || 0) >= 9).length;
const highCount = cves.filter(c => (c.cvss || 0) >= 7 && (c.cvss || 0) < 9).length;
const twoYearsAgo = Date.now() - 730 * 86400000;
const recentCves = cves.filter(c => c.published && new Date(c.published).getTime() > twoYearsAgo).length;

let edgarHits = [];
if (edgarRaw && edgarRaw.hits && Array.isArray(edgarRaw.hits.hits)) {
  edgarHits = edgarRaw.hits.hits.slice(0, 8).map(h => ({ form: h._source ? h._source.file_type : '', filed: h._source ? h._source.file_date : '', company: (h._source && h._source.display_names) ? h._source.display_names.join('; ') : '' }));
}
const gh = (github && github.full_name) ? { fullName: github.full_name, stars: github.stargazers_count, forks: github.forks_count, openIssues: github.open_issues_count, lastPush: github.pushed_at, archived: !!github.archived, license: github.license ? github.license.spdx_id : null, createdAt: github.created_at } : null;
const sc = (scorecard && scorecard.score !== undefined && scorecard.checks) ? { score: scorecard.score, date: scorecard.date, weakChecks: (scorecard.checks || []).filter(ch => ch.score >= 0 && ch.score < 5).map(ch => ch.name + ' (' + ch.score + '/10)') } : null;
const osvSummary = (osv && Array.isArray(osv.vulns)) ? { count: osv.vulns.length, ids: osv.vulns.slice(0, 15).map(v => v.id) } : null;
let dd = null;
if (depsdev && Array.isArray(depsdev.versions) && depsdev.versions.length) {
  const def = depsdev.versions.find(v => v.isDefault) || depsdev.versions[depsdev.versions.length - 1];
  dd = { versionCount: depsdev.versions.length, defaultVersion: (def && def.versionKey) ? def.versionKey.version : null, publishedAt: def ? def.publishedAt : null };
}

let sVuln = 0;
if ((kevData.kevMatchCount || 0) > 0) sVuln += 25;
if (maxCvss >= 9) sVuln += 10; else if (maxCvss >= 7) sVuln += 6; else if (maxCvss >= 4) sVuln += 3;
if (epssMax >= 0.5) sVuln += 10; else if (epssMax >= 0.1) sVuln += 5;
if (recentCves >= 5) sVuln += 5;
sVuln = Math.min(35, sVuln);

let sVendor = 0;
if (sc && sc.score < 5) sVendor += 6;
if (gh && gh.archived) sVendor += 8;
if (gh && gh.lastPush && (Date.now() - new Date(gh.lastPush).getTime()) / 86400000 > 365) sVendor += 6;
if (osvSummary && osvSummary.count > 10) sVendor += 4;
if (edgarHits.length > 0 && intake.vendorPublicCompany) sVendor += 3;
if ((newsData.newsCount || 0) >= 5) sVendor += 4;
sVendor = Math.min(15, sVendor);

let sData = Math.min(12, (intake.sensitiveData || []).length * 4);
if (intake.externalSharing) sData += 4;
if (intake.aiTraining === 'yes') sData += 8; else if (intake.aiProcessing && intake.aiTraining !== 'no') sData += 4;
sData = Math.min(20, sData);

let sAccess = 0;
if (intake.permissionLevel === 'system') sAccess += 10; else if (intake.permissionLevel === 'admin') sAccess += 6;
if (intake.kernelDriver) sAccess += 8;
if (intake.browserAllSites) sAccess += 8;
if ((intake.integrations || []).some(i => /microsoft|graph|m365|365|google|workspace/i.test(i))) sAccess += 5;
if ((intake.integrations || []).some(i => /email|file|database|sql/i.test(i))) sAccess += 4;
sAccess = Math.min(20, sAccess);

let sIdentity = 0;
const auth = intake.authMethods || [];
if (!auth.some(a => /sso|saml|oidc/i.test(a))) sIdentity += 4;
if (!auth.some(a => /mfa/i.test(a))) sIdentity += 4;
if (!(intake.adminControls || []).some(a => /audit/i.test(a))) sIdentity += 2;
sIdentity = Math.min(10, sIdentity);

const riskScore = sVuln + sVendor + sData + sAccess + sIdentity;
const riskBand = riskScore >= 75 ? 'Critical' : (riskScore >= 50 ? 'High' : (riskScore >= 25 ? 'Moderate' : 'Low'));

const stopConditions = [];
if ((kevData.kevMatchCount || 0) > 0) stopConditions.push('CISA KEV match - a known exploited vulnerability is associated with this vendor/product');
if (intake.aiTraining === 'yes' && (intake.sensitiveData || []).length) stopConditions.push('Customer data used for AI model training while sensitive data is in scope');
if (intake.kernelDriver) stopConditions.push('Kernel-level component requires explicit justification');
if (intake.permissionLevel === 'system') stopConditions.push('SYSTEM/root access requested');
if (gh && gh.archived) stopConditions.push('Open-source project is archived/abandoned (unsupported)');

let recommendation;
if (stopConditions.length) recommendation = 'Escalate - automatic stop condition triggered';
else if (riskScore < 25 && base.riskTier === 1) recommendation = 'Approved';
else if (riskScore < 50) recommendation = 'Approved with Conditions';
else if (riskScore < 75) recommendation = 'Pilot Only';
else recommendation = 'Denied (pending analyst confirmation)';
if (intake.existingAlternative) recommendation += ' | Evaluate Use Existing Standard: ' + intake.existingAlternative;

const scoreBreakdown = { vulnerabilityIntel: sVuln + '/35', vendorPosture: sVendor + '/15', dataExposure: sData + '/20', accessFootprint: sAccess + '/20', identityGaps: sIdentity + '/10' };

const promptEvidence = {
  request: { trackingId: intake.trackingId, product: intake.productName, vendor: intake.vendorName, version: intake.requestedVersion, url: intake.productUrl, businessNeed: intake.businessNeed, department: intake.department, userCount: intake.userCount, deployment: intake.deploymentTypes, dataTypes: intake.dataTypes, sensitiveData: intake.sensitiveData, permissionLevel: intake.permissionLevel, kernelDriver: intake.kernelDriver, browserAllSites: intake.browserAllSites, integrations: intake.integrations, oauthScopes: intake.oauthScopes, aiProcessing: intake.aiProcessing, aiTraining: intake.aiTraining, hosting: (intake.hostingProvider || '') + ' / ' + (intake.hostingRegion || ''), authMethods: intake.authMethods, adminControls: intake.adminControls, businessCriticality: intake.businessCriticality, existingAlternative: intake.existingAlternative, externalSharing: intake.externalSharing, publicFacing: intake.publicFacing, notes: intake.notes },
  riskTier: base.riskTierLabel,
  riskFlags: base.riskFlags,
  weightedRiskScore: riskScore + '/100 (' + riskBand + ')',
  scoreBreakdown,
  stopConditions,
  systemRecommendation: recommendation,
  nvd: { totalResults: cveData.totalResults, analyzed: cves.length, criticalCount, highCount, recentCves, maxCvss, epssMax, topCves: cves.slice(0, 10).map(c => ({ id: c.cveId, cvss: c.cvss, severity: c.severity, epss: c.epss, published: c.published, summary: (c.description || '').slice(0, 200) })) },
  cisaKev: kevData.kevMatches,
  breachNewsDiscovery: (newsData.newsItems || []).map(n => ({ title: n.title, date: n.pubDate })),
  secEdgarFilings: edgarHits,
  githubRepo: gh,
  openssfScorecard: sc,
  osv: osvSummary,
  depsDev: dd
};

const lines = [];
lines.push('You are a senior third-party software risk analyst at Automated Intelligent Solutions, performing supply-chain due diligence aligned with NIST SP 800-161 and the NIST SP 1326 due-diligence quick-start guide.');
lines.push('Analyze the following evidence package for a software vetting request and write a professional assessment in markdown.');
lines.push('Required sections, in this order:');
lines.push('## Executive Summary (3-5 sentences, plain business language)');
lines.push('## Vulnerability Assessment (interpret CVE, CISA KEV and EPSS jointly; never rely on CVSS alone; lead with anything exploited in the wild)');
lines.push('## Vendor & Supply-Chain Posture (provenance, resilience, maturity signals, OSS health if applicable)');
lines.push('## Data Security & Privacy (data collected, AI training exposure, residency, subprocessor concerns)');
lines.push('## Identity & Access (SSO/MFA/SCIM/RBAC gaps, OAuth scope concerns, least privilege)');
lines.push('## Safer or Easier-to-Manage Alternatives (2-4 realistic alternatives; prefer capabilities the organization likely already owns in a Microsoft 365 environment when equivalent; one or two sentences each on why)');
lines.push('## Recommended Decision (exactly one of: Approved / Approved with Conditions / Pilot Only / Denied / Use Existing Standard, followed by rationale)');
lines.push('## Conditions & Required Controls (bullet list, concrete and enforceable, e.g. SSO required, restrict OAuth scopes, disable AI training, managed deployment only)');
lines.push('## Open Questions for the Vendor (bullet list)');
lines.push('Rules: be specific and evidence-based; where evidence is missing, say so explicitly instead of guessing; news items are discovery signals that must be confirmed with primary sources; note that this is an advisory recommendation and a human analyst makes the final decision for Tier 3 requests; never state that the product or this review guarantees legal or regulatory compliance.');
lines.push('');
lines.push('EVIDENCE PACKAGE (JSON):');
lines.push(JSON.stringify(promptEvidence, null, 1));
const aiPrompt = lines.join('\n');

return [{ json: { intake, riskTier: base.riskTier, riskTierLabel: base.riskTierLabel, riskFlags: base.riskFlags, riskScore, riskBand, scoreBreakdown, stopConditions, recommendation, cves, maxCvss, epssMax, criticalCount, highCount, kevMatches: kevData.kevMatches || [], kevMatchCount: kevData.kevMatchCount || 0, newsItems: newsData.newsItems || [], edgarHits, github: gh, scorecard: sc, osv: osvSummary, depsDev: dd, aiPrompt } }];

const j = $json;
let aiText = '';
if (j && Array.isArray(j.content) && j.content.length && j.content[0].text) aiText = j.content[0].text;
else if (j && typeof j.text === 'string') aiText = j.text;
else if (j && j.message && Array.isArray(j.message.content) && j.message.content.length) aiText = j.message.content[0].text || '';
const ev = $('Compile Risk Evidence').first().json;
if (!aiText) aiText = '## AI Analysis Unavailable\nThe Claude analysis step did not return output (check the Anthropic credential). The quantitative evidence in this report still applies.';

function esc(s) { return String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function mdToHtml(md) {
  const out = [];
  let inList = false;
  const fmt = (t) => esc(t).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\*(.+?)\*/g, '<em>$1</em>');
  for (const raw of String(md).split('\n')) {
    const line = raw.trimEnd();
    if (/^\s*[-*] /.test(line)) {
      if (!inList) { out.push('<ul style="margin:4px 0 10px 22px;padding:0;">'); inList = true; }
      out.push('<li style="margin:3px 0;">' + fmt(line.replace(/^\s*[-*] /, '')) + '</li>');
      continue;
    }
    if (inList) { out.push('</ul>'); inList = false; }
    if (/^### /.test(line)) out.push('<h4 style="color:#1a365d;margin:14px 0 6px;">' + fmt(line.slice(4)) + '</h4>');
    else if (/^## /.test(line)) out.push('<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">' + fmt(line.slice(3)) + '</h3>');
    else if (/^# /.test(line)) out.push('<h3 style="color:#1a365d;margin:18px 0 8px;">' + fmt(line.slice(2)) + '</h3>');
    else if (line !== '') out.push('<p style="margin:6px 0;">' + fmt(line) + '</p>');
  }
  if (inList) out.push('</ul>');
  return out.join('');
}

const td = 'padding:6px 8px;border:1px solid #e2e8f0;font-size:13px;';
const th = 'padding:6px 8px;border:1px solid #e2e8f0;font-size:12px;background:#edf2f7;text-align:left;color:#1a365d;';
const bandColor = ev.riskBand === 'Critical' ? '#c53030' : (ev.riskBand === 'High' ? '#dd6b20' : (ev.riskBand === 'Moderate' ? '#d69e2e' : '#2f855a'));
const intake = ev.intake || {};

const summaryRows = [['Product', (intake.productName || '') + (intake.requestedVersion ? ' v' + intake.requestedVersion : '')], ['Vendor', intake.vendorName], ['Tracking ID', intake.trackingId], ['Requested by', (intake.requesterName || '') + ' (' + (intake.requesterEmail || '') + ') - ' + (intake.department || '')], ['Business need', intake.businessNeed], ['Deployment', (intake.deploymentTypes || []).join(', ')], ['Users', intake.userCount], ['Data in scope', (intake.dataTypes || []).join(', ') || 'None declared'], ['Sensitive data', (intake.sensitiveData || []).join(', ') || 'None declared'], ['Review tier', ev.riskTierLabel]].map(r => '<tr><td style="' + td + 'font-weight:600;width:160px;">' + esc(r[0]) + '</td><td style="' + td + '">' + esc(r[1]) + '</td></tr>').join('');

const sb = ev.scoreBreakdown || {};
const scoreRows = [['Vulnerability intelligence (KEV/EPSS/CVSS)', sb.vulnerabilityIntel], ['Vendor & supply-chain posture', sb.vendorPosture], ['Data exposure', sb.dataExposure], ['Access footprint', sb.accessFootprint], ['Identity & access gaps', sb.identityGaps]].map(r => '<tr><td style="' + td + '">' + esc(r[0]) + '</td><td style="' + td + 'text-align:center;">' + esc(r[1]) + '</td></tr>').join('');

const flagsHtml = (ev.riskFlags || []).length ? '<ul style="margin:4px 0 10px 22px;padding:0;">' + ev.riskFlags.map(f => '<li style="margin:3px 0;font-size:13px;">' + esc(f) + '</li>').join('') + '</ul>' : '<p style="margin:6px 0;font-size:13px;">None identified at intake.</p>';

const stopsHtml = (ev.stopConditions || []).length ? '<div style="background:#fff5f5;border:1px solid #fc8181;border-radius:6px;padding:10px 14px;margin:10px 0;"><strong style="color:#c53030;">STOP - Automatic escalation conditions</strong><ul style="margin:6px 0 0 20px;padding:0;">' + ev.stopConditions.map(s => '<li style="margin:3px 0;font-size:13px;">' + esc(s) + '</li>').join('') + '</ul></div>' : '';

const cveRows = (ev.cves || []).slice(0, 10).map(c => '<tr><td style="' + td + '"><a href="https://nvd.nist.gov/vuln/detail/' + esc(c.cveId) + '" style="color:#2b6cb0;">' + esc(c.cveId) + '</a></td><td style="' + td + 'text-align:center;">' + (c.cvss === null || c.cvss === undefined ? '-' : c.cvss) + '</td><td style="' + td + 'text-align:center;">' + esc(c.severity || '') + '</td><td style="' + td + 'text-align:center;">' + (c.epss === null || c.epss === undefined ? '-' : (c.epss * 100).toFixed(2) + '%') + '</td><td style="' + td + '">' + esc((c.published || '').slice(0, 10)) + '</td></tr>').join('');
