const newsHtml = (ev.newsItems || []).length ? '<ul style="margin:4px 0 10px 22px;padding:0;">' + ev.newsItems.slice(0, 8).map(n => '<li style="margin:3px 0;font-size:13px;"><a href="' + esc(n.link) + '" style="color:#2b6cb0;">' + esc(n.title) + '</a> <span style="color:#718096;">(' + esc((n.pubDate || '').slice(0, 16)) + ')</span></li>').join('') + '</ul><p style="margin:4px 0;font-size:12px;color:#718096;">Discovery only - confirm material findings against vendor disclosures, SEC filings, or government sources.</p>' : '<p style="margin:6px 0;font-size:13px;">No breach/incident news matched the search.</p>';

const edgarHtml = (ev.edgarHits || []).length ? '<ul style="margin:4px 0 10px 22px;padding:0;">' + ev.edgarHits.map(h => '<li style="margin:3px 0;font-size:13px;">' + esc(h.form) + ' filed ' + esc(h.filed) + ' - ' + esc(h.company) + '</li>').join('') + '</ul>' : '<p style="margin:6px 0;font-size:13px;">No SEC EDGAR full-text hits for vendor + cybersecurity (or vendor is private).</p>';

let ossHtml = '';
