if (ev.osv) { ossHtml += '<p style="margin:6px 0;font-size:13px;"><strong>OSV.dev:</strong> ' + esc(ev.osv.count) + ' package vulnerabilities' + ((ev.osv.ids || []).length ? ' (' + esc(ev.osv.ids.slice(0, 8).join(', ')) + ')' : '') + '</p>'; }
