'<div style="background:#1a365d;padding:22px 28px;"><div style="color:#ffffff;font-size:20px;font-weight:700;">Automated Intelligent Solutions</div><div style="color:#90cdf4;font-size:14px;">Software Vetting &amp; Supply-Chain Risk Report</div></div>' +
'<div style="padding:24px 28px;">' +
'<div style="display:inline-block;background:' + bandColor + ';color:#ffffff;border-radius:6px;padding:8px 16px;font-size:15px;font-weight:700;margin-bottom:6px;">Risk Score: ' + ev.riskScore + '/100 (' + ev.riskBand + ')</div>' +
'<p style="margin:8px 0;font-size:15px;"><strong>System recommendation:</strong> ' + esc(ev.recommendation) + '</p>' +
'<p style="margin:4px 0 14px;font-size:12px;color:#718096;">Advisory only - final decision requires analyst sign-off. Decisions: Approved / Approved with Conditions / Pilot Only / Denied / Use Existing Standard.</p>' +
stopsHtml +
'<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">Request Summary</h3><table style="border-collapse:collapse;width:100%;">' + summaryRows + '</table>' +
'<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">Weighted Risk Score</h3><table style="border-collapse:collapse;width:100%;">' + scoreRows + '</table>' +
'<h4 style="color:#1a365d;margin:14px 0 6px;">Risk flags at intake</h4>' + flagsHtml +
'<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">Vulnerability Intelligence</h3>' + kevHtml + cveTable +
'<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">Breach &amp; Incident Discovery</h3>' + newsHtml +
