'<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">Open-Source Supply Chain</h3>' + ossHtml +
'<h3 style="color:#1a365d;border-bottom:2px solid #2b6cb0;padding-bottom:4px;margin:18px 0 8px;">AI Analyst Assessment</h3>' + mdToHtml(aiText) +
'<div style="background:#ebf8ff;border:1px solid #90cdf4;border-radius:6px;padding:10px 14px;margin:16px 0;font-size:12px;color:#2c5282;">This report is automated evidence gathering to support a human vetting decision under a NIST SP 800-161 / SP 1326-aligned process. It is advisory only and does not create, provide, automate, or guarantee legal or regulatory compliance.</div>' +
'</div><div style="background:#edf2f7;padding:16px 28px;font-size:12px;color:#4a5568;">Automated Intelligent Solutions, Inc. &middot; automatedintelligentsolutions.com &middot; 404-293-0331 &middot; user@example.com</div></div></body></html>';

const register = {
  trackingId: intake.trackingId || '',
