  requester: intake.requesterName || '',
  requesterEmail: intake.requesterEmail || '',
  riskTier: ev.riskTierLabel || '',
  riskScore: ev.riskScore || 0,
  recommendation: ev.recommendation || '',
  decision: 'Pending analyst review',
  status: 'Report emailed - awaiting decision',
  cveCount: (ev.cves || []).length,
  kevMatches: ev.kevMatchCount || 0,
