  dataClassification: (intake.sensitiveData || []).join(', ') || (intake.dataTypes || []).join(', ') || 'None declared',
  stopConditions: (ev.stopConditions || []).join('; '),
  submittedAt: intake.submittedAt || '',
  reviewDate: new Date().toISOString()
};

